269	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
270	// 只有本地数据保存成功才算修改完成：写盘失败时内存变更随快照一并回滚，
271	// 返回错误与零值事项，不把尚未保存的新值当作修改结果。
272	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
273		itemID = clean(itemID)
274		content = clean(content)
275		constraints = clean(constraints)
276		followOwner = clean(followOwner)
277		if err := requireNonEmpty("事项内容", content); err != nil {
278			return Item{}, err
279		}
280		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
281			return Item{}, err
282		}
283		if !severity.valid() {
284			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
285		}
286	
287		var updated Item
288		err := svc.store.mutate(func(d *Data) error {
289			it, _ := findItem(d, itemID)
290			if it == nil {
291				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
292			}
293			sh, _ := findShift(d, it.CurrentShiftID)
294			if sh == nil || sh.Closed {
295				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
296					ErrShiftClosed, itemID, it.CurrentShiftID)
297			}
298			changes := []string{}
299			if it.Content != content {
300				changes = append(changes, "内容")
301			}
302			if it.Severity != severity {
303				changes = append(changes, "严重程度")
304			}
305			if it.Constraints != constraints {
306				changes = append(changes, "限制条件")
307			}
308			if it.FollowOwner != followOwner {
309				changes = append(changes, "后续负责人")
310			}
311			it.Content = content
312			it.Severity = severity
313			it.Constraints = constraints
314			it.FollowOwner = followOwner
315			it.Events = append(it.Events, ItemEvent{
316				At:     svc.now(),
317				Kind:   "updated",
318				Detail: "修改字段：" + joinOr(changes, "无变更"),
319			})
320			updated = *it
321			return nil
322		})
323		if err != nil {
324			// 保存失败时内存已回滚，不能把尚未保存的新值当作修改结果返回。
325			return Item{}, err
326		}
327		return updated, nil
328	}
