922	// cloneTimePtr 复制时间指针，nil 保持 nil。
923	func cloneTimePtr(t *time.Time) *time.Time {
924		if t == nil {
925			return nil
926		}
927		v := *t
928		return &v
929	}
930	
931	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
932	func cloneItem(it Item) Item {
933		out := it
934		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
935		out.Events = append([]ItemEvent(nil), it.Events...)
936		out.ClosedAt = cloneTimePtr(it.ClosedAt)
937		return out
938	}
939	
940	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
941	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
942		out := s
943		out.ClosedAt = cloneTimePtr(s.ClosedAt)
944		return out
945	}
946	
947	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
948	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
949	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
950		if rec == nil {
951			return nil
952		}
953		out := &ShiftCloseRecord{}
954		if rec.Items != nil {
955			out.Items = make([]CloseItemSnapshot, len(rec.Items))
956			for i, s := range rec.Items {
957				out.Items[i] = cloneCloseItemSnapshot(s)
958			}
959		}
960		return out
961	}
962	
963	// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
964	func cloneShift(sh Shift) Shift {
965		out := sh
966		out.ClosedAt = cloneTimePtr(sh.ClosedAt)
967		out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
968		return out
969	}
970	
971	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
972	func cloneEntry(e HandoverEntry) HandoverEntry {
973		out := e
974		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
975		if e.Rounds != nil {
976			out.Rounds = make([]ReturnRound, len(e.Rounds))
977			for i, r := range e.Rounds {
978				out.Rounds[i] = r
979				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
980				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
981			}
982		}
983		return out
984	}
985	
986	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
987	func cloneHandover(h Handover) Handover {
988		out := h
989		out.CompletedAt = cloneTimePtr(h.CompletedAt)
990		if h.Entries != nil {
991			out.Entries = make([]HandoverEntry, len(h.Entries))
992			for i, e := range h.Entries {
993				out.Entries[i] = cloneEntry(e)
994			}
995		}
996		return out
997	}
998	
999	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
1000	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
1001	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
1002	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
1003	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
1004	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
1005	// 也不会改写这份报告；再次查询才反映最新内容。
1006	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
1007		shiftID = clean(shiftID)
1008		d := &svc.store.data
1009		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
1010		sh, _ := findShift(d, shiftID)
1011		if sh == nil {
1012			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
1013		}
1014		rep.Shift = cloneShift(*sh)
1015	
1016		for _, n := range d.Notes {
1017			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
1018				rep.OverlapNotes = append(rep.OverlapNotes, n)
1019			}
1020		}
1021		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
1022	
1023		switch {
1024		case !sh.Closed:
1025			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
1026			rep.Items = currentItemsOfShift(d, sh.ID)
1027		case sh.CloseRecord != nil:
1028			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
1029			rep.ItemsAtClose = true
1030			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
1031			for i, s := range sh.CloseRecord.Items {
1032				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
1033			}
1034			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
1035			for _, s := range rep.CloseItems {
1036				if it, _ := findItem(d, s.ItemID); it != nil {
1037					rep.LatestItems[s.ItemID] = cloneItem(*it)
1038				}
1039			}
1040		default:
1041			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
1042			rep.HistoryIncomplete = true
1043			rep.Items = currentItemsOfShift(d, sh.ID)
1044		}
1045		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
1046		for i := range rep.Items {
1047			rep.Items[i] = cloneItem(rep.Items[i])
1048		}
1049	
1050		for i := range d.Handovers {
1051			h := &d.Handovers[i]
1052			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
1053			if !involved {
1054				continue
1055			}
1056			if h.FromShiftID == sh.ID {
1057				cp := cloneHandover(*h)
1058				rep.Outgoing = &cp
1059			}
1060			if h.ToShiftID == sh.ID {
1061				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
1062			}
1063			for j := range h.Entries {
1064				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
1065					HandoverID: h.ID,
1066					FromShift:  h.FromShiftID,
1067					ToShift:    h.ToShiftID,
1068					Entry:      cloneEntry(h.Entries[j]),
1069				})
1070			}
1071		}
1072		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
1073		for k := range rep.Results {
1074			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
1075		}
1076		return rep, nil
1077	}
