701		}
702		got, _ = f.svc.GetHandover(h.ID)
703		for i := range got.Entries {
704			if got.Entries[i].ItemID == idA {
705				ea = &got.Entries[i]
706			}
707		}
708		if len(ea.Rounds) != 2 {
709			t.Fatalf("应保留历次退回记录，期望2轮，got %d", len(ea.Rounds))
