1321	// TestReturnedMustWaitForResubmit：退回表示等待交班人补充；未重新提交前，
1322	// 确认、继续跟踪、再次退回应报状态错误，且不增加退回轮次、不覆盖上次处理人
1323	// 与时间、不调整后续负责人、不移动事项班次，交接完成情况也不变。
1324	func TestReturnedMustWaitForResubmit(t *testing.T) {
1325		f := newFixture(t)
1326		a, b, items := prepareHandover(t, f)
1327		h, _ := f.svc.CreateHandover(a.ID, b.ID)
1328		idA, idB := items[0].ID, items[1].ID
1329	
1330		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "信息不全，需补充图纸", "", ""); err != nil {
1331			t.Fatalf("return: %v", err)
1332		}
1333		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
1334			t.Fatalf("confirm idB: %v", err)
1335		}
1336	
1337		before, _ := f.svc.GetHandover(h.ID)
1338		eaBefore := findEntryOf(t, before, idA)
1339		returnedAt := eaBefore.ProcessedAt
