// findEntryOf 从交接记录中取出指定事项的当前记录。
func findEntryOf(t *testing.T, h Handover, itemID string) *HandoverEntry {
	t.Helper()
	for i := range h.Entries {
		if h.Entries[i].ItemID == itemID {
			return &h.Entries[i]
		}
